{
  "predictors": [
    {
      "name": "Earnings Stability",
      "construction": "Calculate the standard deviation of quarterly earnings per share (EPS) over the past 5 years.",
      "rationale": "Firms with stable earnings are perceived as less risky and might be undervalued by risk-averse investors.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Debt Issuance Shock",
      "construction": "Measure the percentage change in total debt outstanding from one fiscal year to the next.",
      "rationale": "Sudden increases in debt may signal aggressive expansion or financial strain, impacting future performance.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Management Tenure",
      "construction": "Average the tenure of top executive officers in years.",
      "rationale": "Longer management tenure may indicate stability and strategic consistency, affecting investor perceptions.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "R&D to Sales Ratio",
      "construction": "Divide total research and development expenses by total sales for the fiscal year.",
      "rationale": "High R&D spending relative to sales suggests investment in innovation, potentially leading to future growth.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Dividend Initiation",
      "construction": "Binary variable indicating if the firm started paying dividends within the past year.",
      "rationale": "Initiating dividends may signal management's confidence in future cash flows and profitability.",
      "higher_returns_for": "stocks that initiated dividends"
    },
    {
      "name": "Customer Concentration",
      "construction": "Ratio of sales to largest customer relative to total sales, sourced from annual reports.",
      "rationale": "High customer concentration may imply revenue risk but also strong competitive positioning.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Patent Activity Intensity",
      "construction": "Count the number of patents filed by the firm over the past 3 years.",
      "rationale": "Active patenting can indicate a focus on innovation, potentially leading to competitive advantages.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Environmental Violations",
      "construction": "Count the number of environmental regulatory violations reported over the past 5 years.",
      "rationale": "Frequent violations may indicate operational risks and potential for costly regulatory actions.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Supplier Diversity",
      "construction": "Number of different suppliers used by the firm, as reported in procurement disclosures.",
      "rationale": "A diversified supplier base can reduce operational risk and enhance supply chain resilience.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Market Sentiment Score",
      "construction": "Sentiment analysis score calculated from news articles and financial reports over the past year.",
      "rationale": "Positive sentiment reflects favorable perceptions of the firm's prospects, possibly underappreciated by the market.",
      "higher_returns_for": "high values of the measure"
    }
  ]
}
